python3 -c "
import csv, re

def parse_val(s):
    s = s.strip()
    if s == '': return None
    s = s.replace(',', '.')
    try:
        return float(s)
    except:
        return None

with open('/root/environment/data/ckd_lab_data.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)

    # Collect all values per column
    cols_data = {h: [] for h in header[1:]}
    for row in reader:
        for j in range(1, len(row)):
            v = parse_val(row[j])
            if v is not None:
                cols_data[header[j]].append(v)

    # Print stats
    for col in header[1:]:
        vals = cols_data[col]
        if vals:
            print(f'{col}: min={min(vals):.4f}, max={max(vals):.4f}, median={sorted(vals)[len(vals)//2]:.4f}, count={len(vals)}')
"
